#include <stdio.h>

// 관련된 두 숫자를 한 값으로 묶어요.
typedef struct {
    int count;
    int code;
} Stock;

int main(void) {
    // 이름으로 필요한 필드를 골라 읽어요.
    Stock item = {2, 7};
    printf("%d\n", item.count);
    printf("%d", item.code);
    return 0;
}

#include <stdio.h>

// 관련된 두 숫자를 한 값으로 묶어요.
typedef struct {
    int count;
    int code;
} Stock;

int main(void) {
    // 구조체 값 자체를 다른 변수로 복사해요.
    Stock a = {2, 7};
    Stock b = a;
    // 복사한 b의 필드만 바꿔요.
    b.count = 5;
    printf("%d\n", a.count);
    printf("%d", b.count);
    return 0;
}

#include <stdio.h>

// 관련된 두 숫자를 한 값으로 묶어요.
typedef struct {
    int count;
    int code;
} Stock;

int main(void) {
    // 구조체가 있는 곳을 p가 가리켜요.
    Stock item = {2, 7};
    Stock *p = &item;
    // 가리킨 구조체의 count를 바꿔요.
    p->count = 5;
    printf("%d", item.count);
    return 0;
}

