#include <stdio.h>

// 같은 함수 타입의 두 계산 규칙이에요.
int add_one(int value) {
    return value + 1;
}
int twice(int value) {
    return value * 2;
}

int main(void) {
    // 함수 자체를 선택한 뒤 값을 넘겨 호출해요.
    int value = 2;
    int (*rule)(int) = add_one;
    printf("%d", rule(value));
    return 0;
}

#include <stdio.h>

// 같은 함수 타입의 두 계산 규칙이에요.
int add_one(int value) {
    return value + 1;
}
int twice(int value) {
    return value * 2;
}
// 받은 규칙을 현재 값에 적용해요.
int apply(int value, int (*rule)(int)) {
    return rule(value);
}

int main(void) {
    // 계산 규칙도 인수로 전달할 수 있어요.
    int value = 2;
    printf("%d", apply(value, add_one));
    return 0;
}

