#include <stdio.h>
int main(void) {
    // 둘 다 1인 자리만 남겨요.
    unsigned int value = 5u & 3u;
    printf("%u\n", value);
    return 0;
}

#include <stdio.h>
int main(void) {
    // 영이 아닌 두 값을 참으로 판단해요.
    int value = 2u && 1u;
    printf("%d\n", value);
    return 0;
}

#include <stdio.h>
int main(void) {
    // 어느 한쪽이 1인 자리를 남겨요.
    printf("%u\n", 5u | 2u);
    return 0;
}

#include <stdio.h>
int main(void) {
    // 두 비트가 다른 자리만 남겨요.
    printf("%u\n", 5u ^ 3u);
    return 0;
}

#include <stdio.h>
int main(void) {
    // unsigned의 작은 값을 유효한 범위에서 이동해요.
    printf("%u\n", 1u << 3);
    return 0;
}

#include <stdio.h>
int main(void) {
    // 정수 전체를 반전한 뒤 마스크로 범위를 골라요.
    printf("%u\n", (~5u) & 15u);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    // 필요한 정수 한 개의 공간을 확보해요.
    int *p = malloc(sizeof *p);
    if (p == NULL) return 1;
    // 읽기 전에 반드시 값을 저장해요.
    *p = 7;
    printf("%d\n", *p);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    // 정수 원소의 비트를 영으로 초기화해요.
    int *p = calloc(2, sizeof *p);
    if (p == NULL) return 1;
    printf("%d\n", p[1]);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = malloc(sizeof *p);
    if (p == NULL) return 1;
    // q는 새 저장소가 아니라 같은 할당을 가리켜요.
    int *q = p;
    *q = 9;
    printf("%d\n", *p);
    // 같은 할당은 한 번만 해제해요.
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = malloc(sizeof *p);
    if (p == NULL) return 1;
    // q는 같은 할당을 가리키는 별칭이에요.
    int *q = p;
    *p = 3;
    // 저장소 수명은 여기서 끝나요. p만 NULL로 바꿔요.
    free(p);
    p = NULL;
    // q가 NULL인지 비교해요. 같으면 1, 다르면 0이에요.
    printf("%d\n", q == NULL);
    return 0;
}

